"modules.discovery.card.commandCentre": "Centre de commandes",
"modules.discovery.card.commandCentre.desc": "Ctrl+K : cherchez et lancez tout paramètre, raccourci ou fenêtre. Mettez des favoris pour une barre rapide en jeu.",
"modules.discovery.card.hudHelpers": "Aides HUD",
"modules.discovery.card.hudHelpers.desc": "Flèche de mouvement, compte à rebours de fusion, masse ennemie relative, flèches au bord vers coéquipiers et menaces, panneau de masse des cellules.",
"modules.discovery.card.replayStudio": "Replay Studio",
