"modules.discovery.card.notifications": "Centre de notifications",
"modules.discovery.card.notifications.desc": "Une cloche avec les derniers messages manqués et un mixeur de son par canal.",
"modules.discovery.card.hudEditor": "Éditeur de HUD",
